-- Objetivos de las cuatro etapas de pelota amarilla (catálogo base, tenisXetapas · RFET):
-- Especialización (10-12), Precompetición (12-14), Competición (14-16) y Rendimiento (16-18).
-- Cada etapa es su propio catálogo ("ball" = id de la etapa). Los golpes son bloques de menor a
-- mayor con un objetivo final (is_final) y el golpe nombrado en el título. Idempotente.
ALTER TABLE "tennis_objectives" DROP CONSTRAINT IF EXISTS "tennis_objectives_ball_check";--> statement-breakpoint
ALTER TABLE "tennis_objectives" ADD CONSTRAINT "tennis_objectives_ball_check" CHECK ("ball" IN ('roja','naranja','verde','especializacion','precompeticion','competicion','rendimiento'));--> statement-breakpoint

